---------------------CREATES

CREATE TABLE cprm.cprm_geocron (
    id int4 GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    geom public.geometry(point, 4674) NULL,
    amostra varchar NULL,
    toponimia varchar NULL,
    rocha varchar NULL,
    mtd_geoposi varchar NULL,
    erro_localc varchar NULL,
    mtds varchar NULL,
    mat_analisados varchar NULL,
    nivel_acesso varchar NULL

);
CREATE INDEX cprm_geocron_idx ON cprm.cprm_geocron USING gist (geom);
CREATE INDEX idx_cprm_cprm_geocron ON cprm.cprm_geocron USING btree (id);

