--index Furos de Sondagem

CREATE INDEX cprm_furos_sondagem_idx ON cprm.cprm_furos_sondagem USING gist (geom);
CREATE INDEX idx_cprm_furos_sondagem ON cprm.cprm_furos_sondagem USING btree (ogc_fid);

--mview Furos de Sondagem

create or replace view geoserver.cprm_furos_sondagem as select * from (

WITH collar_summary AS (
    SELECT 
        bhid,
        COUNT(*) AS contagem_de_intervalos,
        STRING_AGG(concat(from_, '-', to_), ', ' ORDER BY from_ ASC) AS intervalos_furo,
        STRING_AGG(DISTINCT unidade_maior, ', ') AS unidades_maiores,
        STRING_AGG(DISTINCT unidade_estratigrafica, ', ') AS unidades_estratigraficas,
        string_agg(distinct url_rigeo, ',') as url_rigeo,
        string_agg(distinct profile_image, ',')  profile_image
    FROM 
        cprm.cprm_furos_sondagem
    GROUP BY 
        bhid
)
SELECT DISTINCT ON (c.bhid)
    c.bhid,
    c.projeto,
    c.xcollar,
    c.ycollar,
    c.zcollar,
    c.end_depth,
    c.geom, 
    c.area_projeto,
    s.profile_image,
    s.contagem_de_intervalos,
    s.intervalos_furo,
    s.unidades_maiores,
    s.unidades_estratigraficas,
    s.url_rigeo
    
FROM 
    cprm.cprm_furos_sondagem c
JOIN 
    collar_summary s ON c.bhid = s.bhid
ORDER BY 
    c.bhid
) a ;

